package com.elektoryk.scan.model;
import org.json.*;import java.util.UUID;
public class ProjectExpense {public enum Category{FOOD,TRAVEL,TOOLS,MATERIAL_EXTRA,OTHER}public String id=UUID.randomUUID().toString();public Category category=Category.OTHER;public double amount=0;public String note="";public long createdAt=System.currentTimeMillis();public JSONObject toJson()throws JSONException{JSONObject o=new JSONObject();o.put("id",id);o.put("category",category.name());o.put("amount",amount);o.put("note",note);o.put("createdAt",createdAt);return o;}public static ProjectExpense fromJson(JSONObject o){if(o==null)return null;ProjectExpense x=new ProjectExpense();x.id=o.optString("id",x.id);try{x.category=Category.valueOf(o.optString("category",Category.OTHER.name()));}catch(Exception ignored){}x.amount=o.optDouble("amount",0);x.note=o.optString("note","");x.createdAt=o.optLong("createdAt",System.currentTimeMillis());return x;}}
